{%- set v_title = ui_def(p['title'], none) -%}
{%- set v_lead = ui_def(p['lead'], '') -%}
{%- set v_badge = ui_def(p['badge'], '') -%}
{%- set v_steps = ui_def(p['steps'], none) -%}
{%- set v_active = ui_def(p['active'], none) -%}
{%- set v_labels = ui_def(p['labels'], none) -%}
{%- set v_layout = ui_def(p['layout'], 'years') -%}
{%- set v_tone = ui_def(p['tone'], 'default') -%}
{%- set v_landmarkLabel = ui_def(p['landmarkLabel'], none) -%}
{%- if ui_t(ui_eq(v_layout, 'years')) %}
  {%- set c_5 -%}
    {%- set c_4 -%}
      {%- for v_s in ui_l(v_steps) %}
        {%- set c_3 -%}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_s, ['date'])) }}
          {%- endset -%}
          {{ ui_include('ui/inline/inline.html.j2', {'p': {'Class': 'text-sm font-semibold'}, 'children': c_1}) }}
          {%- set c_2 -%}
            {{ ui_text(ui_get(v_s, ['tag'])) }}
          {%- endset -%}
          {{ ui_include('ui/inline/inline.html.j2', {'p': {'Class': 'text-xs'}, 'children': c_2}) }}
        {%- endset -%}
        {{ ui_include('ui/button/button.html.j2', {'p': {'Variant': ui_s(('default' if ui_t(ui_eq(ui_get(v_s, ['id']), v_active)) else 'outline')), 'Size': 'lg', 'Type': 'button', 'Class': 'h-auto flex-col items-start gap-0 py-2 text-start', 'Attrs': ui_attrs(['data-testid', 'story-tab', 'data-active', ('true' if ui_t(ui_eq(ui_get(v_s, ['id']), v_active)) else 'false')])}, 'children': c_3}) }}
      {%- endfor %}
    {%- endset -%}
